shacl:
@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:ApplicationComponentDomainShape a sh:NodeShape ;
    sh:class meta:ApplicationComponent ;
    sh:targetSubjectsOf meta:communicatesWith,
        meta:supports .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

meta:ApplicationComponentShape a sh:NodeShape ;
    sh:property [ sh:path meta:communicatesWith ],
        [ sh:path meta:supports ],
        meta:labelShape ;
    sh:targetClass meta:ApplicationComponent .

meta:labelShape a sh:PropertyShape ;
    sh:minCount 1 ;
    sh:path rdfs:label .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:ApprovesEntityTypeRangeShape a sh:NodeShape ;
    sh:class meta:EntityType ;
    sh:targetObjectsOf meta:approvesEntityType .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:ComputerBasedApplicationComponentDomainShape a sh:NodeShape ;
    sh:class meta:ComputerBasedApplicationComponent ;
    sh:targetSubjectsOf meta:softwareProduct,
        meta:typicalFeature .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:DecreasesRangeShape a sh:NodeShape ;
    sh:class meta:EntityType ;
    sh:targetObjectsOf meta:decreases .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:EntityTypeComponentRangeShape a sh:NodeShape ;
    sh:class meta:EntityType ;
    sh:targetObjectsOf meta:entityTypeComponent .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:EntityTypeDomainShape a sh:NodeShape ;
    sh:class meta:EntityType ;
    sh:targetSubjectsOf meta:entityTypeComponent,
        meta:isBasedOn .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

meta:EntityTypeShape a sh:NodeShape ;
    sh:closed true ;
    sh:ignoredProperties ( meta:communicatesWith meta:supports meta:softwareProduct meta:typicalFeature ),
        meta:ignoredProperties,
        meta:topProperties ;
    sh:property [ sh:path meta:entityTypeComponent ],
        [ sh:path meta:isBasedOn ],
        [ sh:hasValue meta:EntityType ;
            sh:path rdf:type ],
        meta:labelShape ;
    sh:targetClass meta:EntityType .

meta:labelShape a sh:PropertyShape ;
    sh:minCount 1 ;
    sh:path rdfs:label .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:FunctionDomainShape a sh:NodeShape ;
    sh:class meta:Function ;
    sh:targetSubjectsOf meta:decreases,
        meta:functionComponent,
        meta:increases,
        meta:updates,
        meta:uses .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

meta:FunctionShape a sh:NodeShape ;
    sh:closed true ;
    sh:ignoredProperties meta:ignoredProperties,
        meta:topProperties ;
    sh:property [ sh:path meta:functionComponent ],
        [ sh:path meta:uses ],
        [ sh:path meta:updates ],
        [ sh:path meta:increases ],
        [ sh:path meta:decreases ],
        [ sh:hasValue meta:Function ;
            sh:path rdf:type ],
        meta:labelShape ;
    sh:targetClass meta:Function .

meta:labelShape a sh:PropertyShape ;
    sh:minCount 1 ;
    sh:path rdfs:label .

