@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:IsBasedOnRangeShape a sh:NodeShape ;
    sh:class meta:EntityType ;
    sh:targetObjectsOf meta:isBasedOn .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:IsResponsibleForEntityTypeRangeShape a sh:NodeShape ;
    sh:class meta:EntityType ;
    sh:targetObjectsOf meta:isResponsibleForEntityType .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:NotEntityTypeShape a sh:NodeShape ;
    sh:not [ a sh:PropertyShape ;
            sh:hasValue meta:EntityType ;
            sh:path ( rdfs:subClassOf rdf:type ) ] ;
    sh:targetClass meta:Function,
        meta:Role .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:NotFunctionShape a sh:NodeShape ;
    sh:not [ a sh:PropertyShape ;
            sh:hasValue meta:Function ;
            sh:path ( rdfs:subClassOf rdf:type ) ] ;
    sh:targetClass meta:EntityType,
        meta:Role .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:NotRoleShape a sh:NodeShape ;
    sh:not [ a sh:PropertyShape ;
            sh:hasValue meta:Role ;
            sh:path ( rdfs:subClassOf rdf:type ) ] ;
    sh:targetClass meta:EntityType,
        meta:Function .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:RoleDomainShape a sh:NodeShape ;
    sh:class meta:Role ;
    sh:targetSubjectsOf meta:isInvolvedIn,
        meta:isResponsibleForFunction,
        meta:isResponsibleForRole,
        meta:roleComponent .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

meta:RoleRangeShape a sh:NodeShape ;
    sh:class meta:Role ;
    sh:targetObjectsOf meta:isResponsibleForRole,
        meta:roleComponent .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

meta:RoleShape a sh:NodeShape ;
    sh:closed true ;
    sh:ignoredProperties meta:ignoredProperties,
        meta:topProperties ;
    sh:property [ sh:path meta:isResponsibleForRole ],
        [ sh:path meta:roleComponent ],
        [ sh:path meta:isInvolvedIn ],
        [ sh:path meta:isResponsibleForFunction ],
        [ sh:path meta:isResponsibleForEntityType ],
        [ sh:path meta:approvesEntityType ],
        [ sh:path meta:approvesFunction ],
        [ sh:hasValue meta:Role ;
            sh:path rdf:type ],
        meta:labelShape ;
    sh:targetClass meta:Role .

meta:labelShape a sh:PropertyShape ;
    sh:minCount 1 ;
    sh:path rdfs:label .

@prefix meta: <http://www.snik.eu/ontology/meta/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

meta:TopShape a sh:NodeShape ;
    sh:property [ sh:path skos:closeMatch ],
        [ sh:path skos:exactMatch ],
        [ sh:path skos:relatedMatch ],
        [ sh:path skos:narrowMatch ],
        [ sh:path skos:broadMatch ],
        [ sh:path meta:homonym ] ;
    sh:targetClass meta:Top ;
    sh:xone ( meta:RoleShape meta:FunctionShape meta:EntityTypeShape ) .

meta:EntityTypeShape a sh:NodeShape ;
    sh:closed true ;
    sh:ignoredProperties ( meta:communicatesWith meta:supports meta:softwareProduct meta:typicalFeature ),
